// Checks controls one by one that only appear in a certain mode (open drawers, filters, forms).
// Usage: node tests/controls.js <preview.html>
const path=require('path');const { chromium } = require('/opt/node-tools/node_modules/playwright');
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1440,height:900}});const errs=[];p.on('pageerror',e=>errs.push(e.message));
const u='file://'+path.resolve(process.argv[2]);await p.goto(u+'#overview');await p.waitForTimeout(500);
const go=async h=>{await p.evaluate(h=>{location.hash=h},h);await p.waitForTimeout(250)};
const res=[];const t=async(name,fn)=>{try{const r=await fn();res.push([r?'OK  ':'FAIL',name])}catch(e){res.push(['FAIL',name+' '+e.message.split('\n')[0]])}};
const drawerOpen=()=>p.evaluate(()=>!document.getElementById('drawer').hidden);const modalOpen=()=>p.evaluate(()=>!document.getElementById('modal').hidden);
const closeAll=async()=>{await p.evaluate(()=>{document.getElementById('modal').hidden=true});const c=await p.$('#drawer:not([hidden]) [data-act=close]');if(c)await c.click()};
await t('Overview pipeline brand link opens brand',async()=>{await go('overview');await p.click('.pipe a.pb');await p.waitForTimeout(200);return (await p.evaluate(()=>location.hash)).startsWith('#brand-')});
await t('Overview brand row opens brand',async()=>{await go('overview');await p.click('main tbody tr.click td:nth-child(3)');await p.waitForTimeout(200);return (await p.evaluate(()=>location.hash)).startsWith('#brand-')});
await t('Signing plan chip opens brand',async()=>{await go('overview');await p.click('.plan .chip');await p.waitForTimeout(200);return (await p.evaluate(()=>location.hash)).startsWith('#brand-')});
await t('SOW board square opens its steps',async()=>{await go('sow');await p.click('[data-act=sowview][data-v=board]');await p.click('button.bd');await p.waitForTimeout(200);const ok=await drawerOpen()&&await p.$('#drawer select[data-code]');return !!ok});
await t('Board drawer: All steps for this brand',async()=>{await p.click('#drawer [data-act=nav-steps]');await p.waitForTimeout(300);return (await p.evaluate(()=>location.hash)).startsWith('#brand-')&&!!(await p.$('.phase'))});
await t('Board Signed square shows SOW stage picker',async()=>{await go('sow');const sq=await p.$$('tbody tr:first-child button.bd');await sq[sq.length-1].click();await p.waitForTimeout(200);const r=!!(await p.$('#drawer select[data-kind=sow]'));await closeAll();return r});
await t('SOW list row opens SOW editor',async()=>{await go('sow');await p.click('[data-act=sowview][data-v=list]');await p.click('tr[data-kind=sow] td:nth-child(3)');await p.waitForTimeout(200);const r=await drawerOpen();await closeAll();return r});
await t('Access grid square opens access editor',async()=>{await go('access');await p.click('[data-act=accview][data-v=grid]');await p.click('button.acd[data-act=open]');await p.waitForTimeout(200);const r=await drawerOpen();await closeAll();return r});
await t('Access grid "Missing access only" filters rows',async()=>{await go('access');const a=(await p.$$('main tbody tr')).length;await p.click('[data-act=accgap][data-v="1"]');await p.waitForTimeout(150);const c=(await p.$$('main tbody tr')).length;await p.click('[data-act=accgap][data-v="0"]');return c<a});
await t('Access grid + creates a row and opens it',async()=>{await go('access');const n=(await p.$$('button.acd[data-act=open]')).length;await p.click('button.acd-empty');await p.waitForTimeout(400);const r=await drawerOpen();await closeAll();await p.waitForTimeout(150);return r&&(await p.$$('button.acd[data-act=open]')).length===n+1});
await t('Add another platform opens form',async()=>{await go('access');await p.click('[data-act=add-access]');await p.waitForTimeout(150);const r=await modalOpen();await closeAll();return r});
await t('Access list filters work',async()=>{await go('access');await p.click('[data-act=accview][data-v=list]');const a=(await p.$$('main tbody tr')).length;await p.selectOption('select[data-k=accStatus]','Granted');await p.waitForTimeout(150);const c=(await p.$$('main tbody tr')).length;await p.selectOption('select[data-k=accStatus]','');await p.click('[data-act=accview][data-v=grid]');return c<a&&c>0});
await t('Brand team card opens team list',async()=>{await go('brand-bespoke');await p.click('button[data-tab=tasks]');await p.click('button.team:not(.empty-team)');await p.waitForTimeout(200);return !!(await p.$('.teamnav'))});
await t('Team chip switches team',async()=>{const h=await p.$eval('main table',e=>e.innerText);const c=(await p.$$('.teamnav .chipbtn'))[1];await c.click();await p.waitForTimeout(150);return (await p.$eval('main table',e=>e.innerText).catch(()=>''))!==h});
await t('Open / All filter on team list',async()=>{const a=(await p.$$('main tbody tr')).length;await p.click('[data-act=tflt][data-v=all]');await p.waitForTimeout(150);const c=(await p.$$('main tbody tr')).length;await p.click('[data-act=tflt][data-v=open]');return c>=a});
await t('Task row opens task editor',async()=>{await p.click('main tbody tr.click');await p.waitForTimeout(200);const r=await drawerOpen();await closeAll();return r});
await t('Add task opens form',async()=>{await p.click('[data-act=add-task]');await p.waitForTimeout(150);const r=await modalOpen();await closeAll();return r});
await t('All teams back button',async()=>{await p.click('[data-act=dept][data-dep=""]');await p.waitForTimeout(150);return !!(await p.$('.teams'))});
await t('Steps tab: show all phases',async()=>{await p.click('button[data-tab=steps]');await p.waitForTimeout(150);const a=await p.$$eval('details.phase',d=>d.filter(x=>x.open).length);await p.click('[data-act=allphases]');await p.waitForTimeout(150);const c=await p.$$eval('details.phase',d=>d.filter(x=>x.open).length);await p.click('[data-act=allphases]');return c>a});
await t('Step Edit opens step editor',async()=>{for(const e of await p.$$('.step [data-act=open]')){if(await e.isVisible()){await e.click();break}}await p.waitForTimeout(200);const r=await drawerOpen();await closeAll();return r});
await t('Mark phase done asks to confirm',async()=>{const x=await p.$('[data-act=phase-done]');if(!x)return 'none';await x.click();await p.waitForTimeout(150);const r=await modalOpen();await closeAll();return r});
await t('Brand Edit details opens editor',async()=>{await p.click('.bhead [data-act=open][data-kind=brand]');await p.waitForTimeout(150);const r=await drawerOpen();await closeAll();return r});
await t('Brand access/SOW/BP tabs render',async()=>{for(const k of ['access','sow','bp']){await p.click(`button[data-tab=${k}]`);await p.waitForTimeout(120)}return !!(await p.$('main .tw'))});
await t('BP grid row opens BP editor',async()=>{await go('bp');await p.click('main tbody tr.click td:nth-child(2)');await p.waitForTimeout(150);const r=await drawerOpen();await closeAll();return r});
await t('Add brand opens form',async()=>{await p.click('[data-act=add-brand]');await p.waitForTimeout(150);const r=await modalOpen();await closeAll();return r});
await t('Settings: add person opens form',async()=>{await go('settings');await p.click('[data-act=settab][data-tab=people]');await p.click('[data-act=add-person]');await p.waitForTimeout(150);const r=await modalOpen();await closeAll();return r});
await t('Settings: every tab renders',async()=>{for(const k of ['lists','steps','nobrand','log','export','people']){await p.click(`[data-act=settab][data-tab=${k}]`);await p.waitForTimeout(100)}return true});
await t('My tasks: Onboarded brands tab',async()=>{await p.selectOption('#whoSel','Noopur');await go('mine');await p.click('[data-act=minetab][data-v=live]');await p.waitForTimeout(150);const r=!!(await p.$('[data-act=minetab][data-v=live].on'));await p.click('[data-act=minetab][data-v=onboarding]');return r});
await t('My tasks: brand cards in onboarding tab',async()=>{return (await p.$$('.bcard')).length>0});
await t('My tasks: every Group by and Sort by option renders',async()=>{await p.click('[data-act=minetab][data-v=all]');for(const g of ['brand','priority','due','status','team','none'])for(const so of ['urgency','due','priority','brand']){await p.selectOption('#m-group',g);await p.selectOption('#m-sort',so);await p.waitForTimeout(40);if(!(await p.$('main .item')))return false}await p.selectOption('#m-group','brand');await p.selectOption('#m-sort','urgency');return true});
await t('My tasks: fold one group',async()=>{const b=await p.$('[data-act=mfold1]');await b.click();await p.waitForTimeout(100);const f=await p.$eval('[data-act=mfold1]',e=>e.getAttribute('aria-expanded'));await p.click('[data-act=mfold1]');return f==='false'});
await t('My tasks: board layout and back',async()=>{await p.click('[data-act=mlayout][data-v=board]');await p.waitForTimeout(100);const ok=!!(await p.$('.kb'));await p.click('[data-act=mlayout][data-v=list]');return ok});
await t('My tasks: item title opens it on its brand page',async()=>{await p.click('.item:not(.men) .t a');await p.waitForTimeout(400);return (await p.evaluate(()=>location.hash)).startsWith('#brand-')&&!!(await p.$('.flash'))});
await t('Light / Dark switch',async()=>{await p.click('[data-act=theme][data-v=dark]');const d=await p.evaluate(()=>document.documentElement.dataset.theme);await p.click('[data-act=theme][data-v=light]');return d==='dark'});
await t('Simple / Full keeps you on the same page',async()=>{await go('overview');await p.click('[data-act=simple][data-v="1"]');await p.waitForTimeout(150);const h=await p.evaluate(()=>location.hash);await p.click('[data-act=simple][data-v="0"]');return h==='#overview'});
await t('Overview: Needs attention row opens the brand on the right tab',async()=>{await go('overview');const r=await p.$('tr[data-act=att-go]');if(!r)return 'none';const tab=await r.getAttribute('data-tab');await r.click();await p.waitForTimeout(250);return (await p.evaluate(()=>location.hash)).startsWith('#brand-')&&!!(await p.$('button[data-tab="'+tab+'"].on'))});
await t('Overview: Missing information links work',async()=>{await go('overview');const a=await p.$('.hyg a');if(!a)return 'none';await a.click();await p.waitForTimeout(200);return (await p.evaluate(()=>location.hash)).length>1});
await t('Guide: Got it hides the guide',async()=>{await go('people');const g=await p.$('[data-act=guide-off]');if(!g)return 'already hidden';await g.click();await p.waitForTimeout(150);return !(await p.$('.guide'))});
await t('People: click a person, click again to close',async()=>{await go('people');await p.click('main tbody tr.click');await p.waitForTimeout(150);const a=(await p.$$('main .item')).length;await p.click('main tbody tr.click');await p.waitForTimeout(150);return a>0&&(await p.$$('main .item')).length===0});
await t('People: No owner row lists unowned tasks',async()=>{const r=await p.$('tr[data-act=person-pick][data-name=__none]');if(!r)return 'none';await r.click();await p.waitForTimeout(150);return (await p.$eval('main',e=>e.innerText)).includes('Tasks with no owner')});
await t('Search: Escape clears it',async()=>{await p.click('#q');await p.keyboard.type('kndz');await p.waitForTimeout(100);await p.keyboard.press('Escape');await p.waitForTimeout(100);return await p.evaluate(()=>document.querySelector('#q').value==='')});
await t('Search: / key focuses search',async()=>{await go('overview');await p.click('main h1');await p.keyboard.press('/');return await p.evaluate(()=>document.activeElement.id==='q')});
await t('Search: person result opens People with them picked',async()=>{await p.keyboard.type('Cyrus');await p.waitForTimeout(120);const rows=await p.$$('#sres .sr-row');let hit=null;for(const r of rows)if((await r.innerText()).toLowerCase().startsWith('person'))hit=r;if(!hit)return false;await hit.click();await p.waitForTimeout(250);return (await p.evaluate(()=>location.hash))==='#people'&&!!(await p.$('tr.sel'))});
await t('Brand: Updates tab, post and delete a comment',async()=>{await p.selectOption('#whoSel','Noopur');await go('brand-ora');await p.click('button[data-tab=updates]');await p.fill('#c-text','Test note');await p.click('#cform button[type=submit]');await p.waitForTimeout(250);const has=(await p.$eval('main',e=>e.innerText)).includes('Test note');await p.click('[data-act=del-comment]');await p.waitForTimeout(100);await p.click('[data-act=mok]');await p.waitForTimeout(250);return has&&!(await p.$eval('main',e=>e.innerText)).includes('Test note')});
await t('Brand: Client view opens and goes back',async()=>{await go('brand-ora');await p.click('a[href="#client-ora"]');await p.waitForTimeout(200);const ok=!!(await p.$('.client'));await p.click('a[href="#brand-ora"]');await p.waitForTimeout(200);return ok&&(await p.evaluate(()=>location.hash))==='#brand-ora'});
await t('Settings: template delete asks to confirm',async()=>{await go('settings');await p.click('[data-act=settab][data-tab=templates]');await p.fill('#t-name','Tmp');await p.fill('#t-lines','One task');await p.click('#tform button[type=submit]');await p.waitForTimeout(250);await p.click('[data-act=tpl-del]');await p.waitForTimeout(100);const r=await modalOpen();await p.click('[data-act=mok]');await p.waitForTimeout(250);return r&&!(await p.$eval('main',e=>e.innerText)).includes('Tmp')});
for(const [r,n] of res)console.log(r,n);const fails=res.filter(r=>r[0]==='FAIL').length;console.log('\n'+(res.length-fails)+' of '+res.length+' controls work. script errors: '+errs.length);errs.forEach(e=>console.log('  '+e));await b.close();process.exit(fails||errs.length?1:0)})()
